  `highMax` int NOT NULL DEFAULT '80',
  `companyLogo` text COLLATE utf8mb4_unicode_ci,
  `reportHeader` text COLLATE utf8mb4_unicode_ci,
  `reportFooter` text COLLATE utf8mb4_unicode_ci,
  `primaryColor` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#d11c9e',
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  `averageLabel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Médio',
  `highLabel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Alto',
  `lowLabel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Baixo',
  `veryHighLabel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Muito Alto',
  `veryLowLabel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Muito Baixo',
  PRIMARY KEY (`id`),
