  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `traitId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `facetKey` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `weight` double NOT NULL DEFAULT '1',
  `description` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `averageText` text COLLATE utf8mb4_unicode_ci,
  `highText` text COLLATE utf8mb4_unicode_ci,
  `isActive` tinyint(1) NOT NULL DEFAULT '1',
  `lowText` text COLLATE utf8mb4_unicode_ci,
  `veryHighText` text COLLATE utf8mb4_unicode_ci,
  `veryLowText` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `bigfive_facet_configs_traitId_fkey` (`traitId`),
  CONSTRAINT `bigfive_facet_configs_traitId_fkey` FOREIGN KEY (`traitId`) REFERENCES `bigfive_trait_configs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
