DROP TABLE IF EXISTS `bigfive_interpretative_texts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `bigfive_interpretative_texts` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `configId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `traitKey` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scoreRange` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `context` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `text` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updatedAt` datetime(3) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `bigfive_interpretative_texts_configId_traitKey_category_idx` (`configId`,`traitKey`,`category`),
  CONSTRAINT `bigfive_interpretative_texts_configId_fkey` FOREIGN KEY (`configId`) REFERENCES `bigfive_configs` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
