DROP TABLE IF EXISTS `cross_profile_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cross_profile_reports` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `connectionId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `authorId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `targetId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `scoreGap` json NOT NULL,
  `matchLevel` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `createdAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`id`),
  KEY `cross_profile_reports_connectionId_idx` (`connectionId`),
  KEY `cross_profile_reports_authorId_fkey` (`authorId`),
  KEY `cross_profile_reports_targetId_fkey` (`targetId`),
  CONSTRAINT `cross_profile_reports_authorId_fkey` FOREIGN KEY (`authorId`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `cross_profile_reports_connectionId_fkey` FOREIGN KEY (`connectionId`) REFERENCES `connections` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `cross_profile_reports_targetId_fkey` FOREIGN KEY (`targetId`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
