INSERT INTO `interpretation_rules` VALUES ('0f83983c-d06d-48cf-b9f1-bac25eaaf3df','OPENNESS',4,5,'Demonstra alta criatividade e curiosidade intelectual. Tende a buscar inovação e aceitar bem mudanças.','STRENGTH','2025-12-09 03:20:49.997','2025-12-09 03:20:49.997'),('137a3285-5c28-4d58-9a2b-4b9db9421c00','AGREEABLENESS',0,2,'Pode ser percebido como competitivo ou cético. Tende a priorizar a lógica sobre os sentimentos alheios.','RISK','2025-12-09 03:20:50.087','2025-12-09 03:20:50.087'),('534dadb6-3e51-43cb-a230-e686e67b2646','CONSCIENTIOUSNESS',0,2.5,'Pode ter dificuldade com prazos e organização pessoal. Tende a ser mais flexível e espontâneo.','RISK','2025-12-09 03:20:50.074','2025-12-09 03:20:50.074'),('7026c825-d2e5-4fde-be02-3c9589930bff','CONSCIENTIOUSNESS',4.5,5,'Pode se tornar excessivamente perfeccionista ou rígido em processos.','RISK','2025-12-09 03:20:50.061','2025-12-09 03:20:50.061'),('7b1162fc-501a-43d6-8119-99298c427a7d','NEUROTICISM',4,5,'Pode reagir intensamente ao estresse, apresentando ansiedade ou oscilações de humor.','RISK','2025-12-09 03:20:50.099','2025-12-09 03:20:50.099'),('804560ce-be2a-4915-9f74-fc4a5209b940','EXTRAVERSION',4,5,'Comunicador nato, energiza-se com interações sociais e tende a assumir liderança em grupos.','COMMUNICATION_STYLE','2025-12-09 03:20:50.077','2025-12-09 03:20:50.077'),('86b0a1b3-a7ca-48e6-86a7-53d2276f1d32','CONSCIENTIOUSNESS',4,5,'Altamente organizado, disciplinado e focado em resultados. Tende a planejar meticulosamente.','STRENGTH','2025-12-09 03:20:50.056','2025-12-09 03:20:50.056'),('a83f35b3-ab65-420f-af7f-e8c755205855','AGREEABLENESS',4,5,'Altamente colaborativo, empático e focado em harmonia. Excelente para trabalho em equipe.','STRENGTH','2025-12-09 03:20:50.083','2025-12-09 03:20:50.083'),('b0ce6deb-68e7-4ea9-a346-4f578c95e020','EXTRAVERSION',0,2.5,'Mais reservado e reflexivo. Prefere interações um-a-um e ambientes de trabalho mais silenciosos.','COMMUNICATION_STYLE','2025-12-09 03:20:50.080','2025-12-09 03:20:50.080'),('c39a8f69-1982-448e-b799-4729f15f0fc7','NEUROTICISM',0,2,'Demonstra alta resiliência e calma sob pressão. Não se abala facilmente com estresse.','STRENGTH','2025-12-09 03:20:50.097','2025-12-09 03:20:50.097'),('d5d3b31c-eb5f-42a5-b144-1696b04d17d5','AGREEABLENESS',4.5,5,'Pode ter dificuldade em dizer \"não\" ou em lidar com conflitos necessários.','RISK','2025-12-09 03:20:50.092','2025-12-09 03:20:50.092'),('e9208237-01ef-4001-b41d-5c11715d6f9e','OPENNESS',0,2.5,'Pode apresentar resistência a mudanças e preferência por métodos tradicionais.','RISK','2025-12-09 03:20:50.049','2025-12-09 03:20:50.049');
