DROP TABLE IF EXISTS `site_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `site_settings` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tenant_id` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hero_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Descubra os Talentos Ocultos',
  `hero_subtitle` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'na Sua Equipe',
  `hero_description` text COLLATE utf8mb4_unicode_ci,
  `hero_badge` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'NOVA VERSÃO 2.0',
  `hero_bg_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#8F088F',
  `hero_text_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#FFFFFF',
  `primary_button_text` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ver Demonstração',
  `primary_button_link` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '/demo',
  `secondary_button_text` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Conhecer Recursos',
  `secondary_button_link` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT '/features',
  `primary_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#8F088F',
  `secondary_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#F7F7F7',
  `accent_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#FFC107',
  `features` json NOT NULL,
  `pricing_plans` json NOT NULL,
  `show_features` tinyint(1) NOT NULL DEFAULT '1',
  `show_pricing` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` datetime(3) NOT NULL,
  `about_content` text COLLATE utf8mb4_unicode_ci,
  `about_title` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT 'Sobre Nossa Empresa',
  `show_about` tinyint(1) NOT NULL DEFAULT '1',
  `business_features` json NOT NULL,
  `business_hero_badge` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT 'Solução Corporativa',
  `business_hero_bg_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#F0F9FF',
  `business_hero_description` text COLLATE utf8mb4_unicode_ci,
  `business_hero_subtitle` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'com Inteligência Comportamental',
  `business_hero_text_color` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '#111827',
  `business_hero_title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Impulsione o seu Capital Humano',
  `business_logo` longtext COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `site_settings_tenant_id_fkey` (`tenant_id`),
  CONSTRAINT `site_settings_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
